cat > /tmp/oh.c <<'EOF'
#define _GNU_SOURCE
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <dirent.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>

int main(int argc, char **argv){
  if(argc<4){fprintf(stderr,"usage: %s mountdir inode gen [ls]\n",argv[0]);return 2;}
  int mfd = open(argv[1], O_RDONLY|O_DIRECTORY);
  if(mfd<0){perror("open mount");return 1;}
  uint32_t ino = strtoul(argv[2],0,0), gen=strtoul(argv[3],0,0);
  struct file_handle *h = malloc(sizeof(struct file_handle)+64);
  h->handle_bytes=8; h->handle_type=1;
  memcpy(h->f_handle,&ino,4); memcpy(h->f_handle+4,&gen,4);
  int fd = open_by_handle_at(mfd,h,O_RDONLY);
  if(fd<0){perror("open_by_handle_at");return 3;}
  struct stat st; fstat(fd,&st);
  printf("opened ino=%u gen=%u mode=%o size=%ld\n",ino,gen,st.st_mode,(long)st.st_size);
  if(argc>4 && S_ISDIR(st.st_mode)){
    DIR *d=fdopendir(fd);
    struct dirent *de;
    while((de=readdir(d))) printf("%s\n",de->d_name);
  }
  return 0;
}
EOF
